import bpy
ns=bpy.app.driver_namespace['harbor_craft']
exec("# Put the net outside the deck fascia so the timber cannot clip its strands.
for o in c.objects:
    if o.name.startswith(('Net hanging','Net transverse','Net edge rope','Net head hitch')):
        for v in o.data.vertices:v.co.x-=.16
for y in [-3.02,-1.13]:
    tube('Net outer tie',[(-4.47,y,.62),(-4.60,y,.66),(-4.68,y,.61)],.014,rope,7)
# Interior boarding stops daylight leaking through the small exterior seams.
# Openings remain real; no solid wall is placed behind the door or windows.
for a,b in [(-2.63,-2.12),(-1.32,-.90),(.90,1.32),(2.12,2.63)]:
    plank('Front inner board',(-2.255,a,1.64),(-2.255,b,1.64),2.55,.025,20,(-1,0,0),0)
for a,b in [(-2.12,-1.32),(1.32,2.12)]:
    for z,h in [(.87,1.03),(2.59,.69)]:
        plank('Front window inner board',(-2.255,a,z),(-2.255,b,z),h,.025,21,(-1,0,0),0)
plank('Front door header lining',(-2.255,-.90,2.65),(-2.255,.90,2.65),.53,.025,20,(-1,0,0),0)
plank('Rear interior boarding',(2.245,-2.64,1.65),(2.245,2.64,1.65),2.60,.025,20,(1,0,0),0)
plank('Unwindowed side interior',(-2.25,2.645,1.65),(2.25,2.645,1.65),2.60,.025,20,(0,1,0),0)
for a,b in [(-2.25,-.44),(.74,2.25)]:
    plank('Windowed side interior',(a,-2.645,1.65),(b,-2.645,1.65),2.6,.025,20,(0,-1,0),0)
for z,h in [(.85,1.0),(2.61,.68)]:
    plank('Side inner reveal',(-.44,-2.645,z),(.74,-2.645,z),h,.025,20,(0,-1,0),0)
for x in [-2.245,2.245]:
    for row in range(8):
        z=2.98+row*.16;w=max(.12,5.45*(1-(z-2.9)/1.42))
