for side in [-1,1]:
    for j in range(8):
        x=-2.03+j*.58
        plank('Side stone footing '+str((side,j)),(x-.27,side*2.60,.12),(x+.27,side*2.60,.12),.36,.26,21,(0,side,0),.022,stone)
export_asset()
